mapper.select:
select 
from vpn.danmaku_comment
where namespace=#{namespace} and contentId=#{contentId} and editionId=#{editionId}
and deleted=0
and atMs>=#{startMs} and atMs<#{endMs}

	and id>#{cursor}

order by id asc
limit #{limit}

select 
from vpn.danmaku_comment
where namespace=#{namespace} and contentId=#{contentId} and editionId=#{editionId}
and userId=#{userId} and clientMsgId=#{clientMsgId}
limit 1

select count(*)
from vpn.danmaku_comment
where userId=#{userId} and createTime>=#{since}
